"use client";

import { motion } from "framer-motion";
import { useEffect, useState } from "react";

export default function Background() {
    const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            setMousePosition({
                x: (e.clientX / window.innerWidth) * 20 - 10,
                y: (e.clientY / window.innerHeight) * 20 - 10,
            });
        };

        window.addEventListener("mousemove", handleMouseMove);
        return () => window.removeEventListener("mousemove", handleMouseMove);
    }, []);

    return (
        <div className="fixed inset-0 -z-10 bg-background overflow-hidden">
            {/* Subtle radial glow at center */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,var(--glow-color)_0%,transparent_70%)]" />

            {/* Animated white/gray orbs */}
            <motion.div
                animate={{
                    x: mousePosition.x,
                    y: mousePosition.y,
                }}
                transition={{ type: "spring", damping: 30 }}
                className="absolute top-0 right-1/4 h-[500px] w-[500px] rounded-full bg-foreground/5 blur-[120px]"
            />

            <motion.div
                animate={{
                    x: -mousePosition.x,
                    y: -mousePosition.y,
                }}
                transition={{ type: "spring", damping: 30 }}
                className="absolute bottom-0 left-1/4 h-[600px] w-[600px] rounded-full bg-neutral-500/10 blur-[130px]"
            />

            <motion.div
                animate={{
                    scale: [1, 1.1, 1],
                    opacity: [0.2, 0.4, 0.2],
                }}
                transition={{
                    duration: 10,
                    repeat: Infinity,
                    ease: "easeInOut",
                }}
                className="absolute top-1/2 left-1/2 h-[500px] w-[500px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-foreground/5 blur-[100px]"
            />

            {/* Mesh grid overlay - crisp and dark */}
            <div className="absolute inset-0 opacity-[0.03] transition-opacity dark:opacity-10" style={{ backgroundImage: "url('data:image/svg+xml;base64,')" }} />
            <div className="absolute inset-0 opacity-[0.03] hidden dark:block" style={{ backgroundImage: "url('data:image/svg+xml;base64,')" }} />
            
            {/* Vignette effect */}
            <div className="absolute inset-0 bg-background/40 [mask-image:radial-gradient(circle_at_center,transparent_0%,black_100%)] pointer-events-none" />
        </div>
    );
}
